#include <bits/stdc++.h>
using namespace std;

class Solution { public:
 int convertTime(string current,string correct){auto parse=[](string s){return stoi(s.substr(0,2))*60+stoi(s.substr(3,2));};int d=parse(correct)-parse(current),ans=0;
  for(int step:{60,15,5,1}){ans+=d/step;d%=step;}return ans;
 }
